class Solution {
public:
    string majorityFrequencyGroup(string s) {
        int freq[26] = {};
        for (char c : s) ++freq[c - 'a'];
        map<int, string> groups;
        for (int i = 0; i < 26; ++i) {
            if (freq[i]) groups[freq[i]].push_back(char('a' + i));
        }
        string ans;
        for (const auto& entry : groups) {
            if (entry.second.size() >= ans.size()) ans = entry.second;
        }
        return ans;
    }
};
